<template>
 <Teleport to="body"><div class="phrase-overlay" @mousedown.self="close"><section class="phrase-capture card" role="dialog" aria-modal="true" aria-label="收藏原文短语" @keydown.stop @keydown.esc.stop="close" @keydown.tab.prevent="cycleFocus"><h2>收藏原文短语</h2><p v-if="loading">正在核对原文…</p><template v-if="anchor"><blockquote>{{ anchor.quote }}</blockquote><details><summary>原文上下文 · {{ anchor.sourceLabel }}</summary><p class="phrase-context">{{ anchor.context }}</p></details><form v-if="!saved" @submit.prevent="save"><label>此处释义<textarea ref="meaningInput" v-model="meaning" aria-label="短语释义" required maxlength="2000" rows="3" :disabled="busy" placeholder="填写这个语境中的意思" /></label><label>备注<textarea v-model="note" aria-label="短语备注" maxlength="5000" rows="2" :disabled="busy" /></label><label>标签<input v-model="tags" aria-label="短语标签" maxlength="380" :disabled="busy" placeholder="用逗号分隔" /></label><p>保存原文、上下文与出处；复习卡可在保存后另行制作。</p><button class="primary" :disabled="busy||loading">{{ busy?'正在保存…':'保存短语' }}</button></form></template><p v-if="error" role="alert">{{ error }}</p><p v-if="saved" role="status">{{ saved.duplicate?'这处短语已收藏，保留已有释义。':'短语已收藏。' }}<button @click="openSaved">查看收藏并制作练习卡</button></p><button ref="closeButton" :disabled="busy" @click="close">{{ saved?'关闭':'取消' }}</button></section></div></Teleport>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue';import {useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
const props=defineProps({selection:{type:Object,required:true}}),emit=defineEmits(['close']),router=useRouter(),anchor=ref(null),meaning=ref(''),note=ref(''),tags=ref(''),loading=ref(true),busy=ref(false),error=ref(''),saved=ref(null),meaningInput=ref(null),closeButton=ref(null);let disposed=false,operation=null,signature='',priorFocus;
function cycleFocus(event){const controls=[...event.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),summary')],at=controls.indexOf(document.activeElement);controls[(at+(event.shiftKey?-1:1)+controls.length)%controls.length]?.focus();}
function canClose(){return !busy.value&&(!!saved.value||!(meaning.value||note.value||tags.value)||window.confirm('短语还有未保存内容，确定放弃？'));}
function close(){if(canClose())emit('close');}
onBeforeRouteLeave(()=>canClose());onBeforeRouteUpdate(()=>canClose());
async function save(){if(busy.value||!anchor.value)return;const payload={...anchor.value,meaning:meaning.value,note:note.value,tags:tags.value.split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean)},key=JSON.stringify(payload);if(!operation||key!==signature){operation=crypto.randomUUID();signature=key;}busy.value=true;error.value='';try{const r=await window.keeper.phraseSave({...payload,operationId:operation});if(disposed)return;if(!r.ok)throw Error(r.error);saved.value=r;busy.value=false;await nextTick();closeButton.value?.focus();}catch(e){if(!disposed)error.value='保存未确认，可重试；内容保留：'+e.message;}finally{if(!disposed)busy.value=false;}}
async function openSaved(){await router.push('/phrases?phrase='+saved.value.id);}
onMounted(async()=>{priorFocus=document.activeElement;closeButton.value?.focus();try{anchor.value=await window.keeper.phrasePrepare({...props.selection});if(!disposed){await nextTick();meaningInput.value?.focus();}}catch(e){if(!disposed)error.value=e.message;}finally{if(!disposed)loading.value=false;}});
onBeforeUnmount(()=>{disposed=true;priorFocus?.isConnected&&priorFocus.focus?.();});
</script>
<style scoped>.phrase-overlay{position:fixed;inset:0;z-index:160;background:#0005;display:grid;place-items:center;padding:20px}.phrase-capture{width:min(520px,100%);max-height:85vh;overflow:auto;padding:24px;box-sizing:border-box}.phrase-capture h2{font-size:20px}.phrase-capture blockquote{font:20px/1.7 Georgia,serif;margin:12px 0}.phrase-capture label{display:block;font-size:13px;margin:12px 0}.phrase-capture input,.phrase-capture textarea{display:block;width:100%;box-sizing:border-box;padding:9px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);margin-top:4px}.phrase-capture p,.phrase-capture details{font-size:12px;line-height:1.8}.phrase-capture button{margin:6px 8px 0 0}.phrase-context{white-space:pre-wrap}.phrase-capture [role=alert]{color:var(--red)}</style>
